// Extract input data
const companyName = $input.first().json.company_name || 'Unknown Company';
const companyId = $input.first().json.company_id || 'unknown';
const content = $input.first().json.content || '{}';

// Prepare the prompt for Section 1 generation
const prompt = `You are generating Section 1: Introduction & Engagement Context for a due diligence report.

Company: ${companyName}
Company ID: ${companyId}
Company Data: ${content}

Generate ONLY the Section 1 content with the following structure:
- Professional introduction to the company
- Business context and market position
- Key engagement objectives
- Scope of due diligence review

IMPORTANT REQUIREMENTS:
- NO placeholders like [Company Name], {{variable}}, or TBD
- Use the actual company name: ${companyName}
- Provide specific, detailed content
- Format as clean HTML with proper headings
- Maximum 800 words
- Professional tone suitable for executive review

Return ONLY the formatted HTML content, no explanations or metadata.`;

return [{
  json: {
    prompt: prompt,
    company_name: companyName,
    company_id: companyId
  }
}];

// Extract the generated content from Ollama response
const response = $input.first().json;
let generatedContent = '';

if (response.response) {
  generatedContent = response.response;
} else if (response.content) {
  generatedContent = response.content;
} else {
  generatedContent = 'Error: No content generated';
}

// Clean up the content
generatedContent = generatedContent.trim();

// Ensure it's properly formatted HTML
if (!generatedContent.includes('<h') && !generatedContent.includes('<p>')) {
  // Add basic HTML structure if not present
  const paragraphs = generatedContent.split('\n\n').map(p => `<p>${p.trim()}</p>`).join('\n');
  generatedContent = `<div class="section-1">\n${paragraphs}\n</div>`;
}

return [{
  json: {
    section_1_content: generatedContent,
    company_name: $('Process Input Data').first().json.company_name,
    company_id: $('Process Input Data').first().json.company_id,
    generated_at: new Date().toISOString()
  }
}];
